#include <algorithm>
#include <iostream>
#include <vector>

int main() {
    std::vector<int> values{7, 2, 5};
    std::sort(values.begin(), values.end());
    const auto count = std::count_if(values.begin(), values.end(), [](int n) { return n >= 5; });
    std::cout << values.front() << ", count>=5=" << count << '\n';
}
